workedExamples.code:
#include <iostream>

int main() {
    int value{10};
    int copy = value;
    int& alias = value;
    int* pointer = &value;
    alias = 12;
    *pointer = 15;
    std::cout << value << ' ' << copy << ' ' << alias << '\n';
    return 0;
}

#include <iostream>

int main() {
    int first{5};
    int second{9};
    int* selected = &first;
    selected = &second;
    *selected = 7;
    std::cout << first << ' ' << second << '\n';
    return 0;
}

#include <iostream>

int main() {
    int* selected{nullptr};
    if (selected != nullptr) {
        std::cout << *selected << '\n';
    } else {
        std::cout << "absent\n";
    }
    return 0;
}

#include <iostream>

int main() {
    int value{10};
    const int* observer = &value;
    const int& view = value;
    value = 14;
    std::cout << *observer << ' ' << view << '\n';
    return 0;
}

