laboratory.referenceCode:
#include <iostream>

int main() {
    int stock{10};
    int snapshot = stock;
    int& selectedStock = stock;
    int* stockPointer = &stock;
    selectedStock -= 3;
    *stockPointer += 2;
    std::cout << "stock=" << stock << '\n';
    std::cout << "snapshot=" << snapshot << '\n';
    std::cout << "alias=" << selectedStock << '\n';
    return 0;
}

